import Foundation
import Vapor
import Crypto

// MARK: - JWT Token Validation Middleware

struct JWTConfig {
    let secret: Data
    let issuer: String
    let maxClockSkew: Int64  // seconds
    let requiredClaims: Set<String>

    static let `default` = JWTConfig(
        secret: Data("production-secret-key-min-32-bytes!".utf8),
        issuer: "auth.internal.service",
        maxClockSkew: 30,
        requiredClaims: ["sub", "iat", "exp", "iss", "role"]
    )
}

struct JWTClaims {
    let subject: String
    let issuedAt: Int64
    let expiration: Int64
    let issuer: String
    let role: String
    let additionalClaims: [String: Any]
}

enum JWTError: Error {
    case malformedToken
    case invalidSignature
    case missingClaim(String)
    case invalidIssuer
    case tokenExpired
    case tokenNotYetValid
    case invalidEncoding
}

// MARK: - Base64URL Utilities

func base64URLDecode(_ string: String) -> Data? {
    var base64 = string
        .replacingOccurrences(of: "-", with: "+")
        .replacingOccurrences(of: "_", with: "/")
    let remainder = base64.count % 4
    if remainder > 0 {
        base64 += String(repeating: "=", count: 4 - remainder)
    }
    return Data(base64Encoded: base64)
}

func base64URLEncode(_ data: Data) -> String {
    return data.base64EncodedString()
        .replacingOccurrences(of: "+", with: "-")
        .replacingOccurrences(of: "/", with: "_")
        .replacingOccurrences(of: "=", with: "")
}

// MARK: - HMAC Signature Verification

func verifyHMACSignature(header: String, payload: String, signature: String, secret: Data) -> Bool {
    let message = "\(header).\(payload)"
    guard let messageData = message.data(using: .utf8) else { return false }
    let key = SymmetricKey(data: secret)
    let expectedMAC = HMAC<SHA256>.authenticationCode(for: messageData, using: key)
    guard let signatureData = base64URLDecode(signature) else { return false }
    // Constant-time comparison to prevent timing attacks
    let expectedData = Data(expectedMAC)
    guard expectedData.count == signatureData.count else { return false }
    var result: UInt8 = 0
    for (a, b) in zip(expectedData, signatureData) {
        result |= a ^ b
    }
    return result == 0
}

// MARK: - Token Temporal Validation
// This is the core security check that ensures tokens are within their validity window.
// We use arithmetic difference to account for clock skew between distributed services.

func validateTokenTemporal(claims: JWTClaims, config: JWTConfig) -> Result<Void, JWTError> {
    let now = Int64(Date().timeIntervalSince1970)

    // Check if token was issued in the future (with skew allowance)
    let issuedAtDelta = now - claims.issuedAt
    if issuedAtDelta < -config.maxClockSkew {
        return .failure(.tokenNotYetValid)
    }

    // Check token expiration using arithmetic difference
    // A positive remainingLife means the token hasn't expired yet
    let remainingLife = claims.expiration - now

    // Allow for clock skew: token is valid if remainingLife >= -maxClockSkew
    // This means: expiration - now >= -maxClockSkew
    // Which means: expiration >= now - maxClockSkew
    if remainingLife + config.maxClockSkew >= 0 {
        return .success(())
    }

    return .failure(.tokenExpired)
}

// MARK: - Claims Parser

func parseClaims(from payloadData: Data, config: JWTConfig) throws -> JWTClaims {
    guard let json = try? JSONSerialization.jsonObject(with: payloadData) as? [String: Any] else {
        throw JWTError.malformedToken
    }

    // Verify all required claims are present
    for claim in config.requiredClaims {
        guard json[claim] != nil else {
            throw JWTError.missingClaim(claim)
        }
    }

    guard let sub = json["sub"] as? String,
          let iat = json["iat"] as? NSNumber,
          let exp = json["exp"] as? NSNumber,
          let iss = json["iss"] as? String,
          let role = json["role"] as? String else {
        throw JWTError.malformedToken
    }

    // Validate issuer
    guard iss == config.issuer else {
        throw JWTError.invalidIssuer
    }

    var additional: [String: Any] = json
    for key in ["sub", "iat", "exp", "iss", "role"] {
        additional.removeValue(forKey: key)
    }

    return JWTClaims(
        subject: sub,
        issuedAt: iat.int64Value,
        expiration: exp.int64Value,
        issuer: iss,
        role: role,
        additionalClaims: additional
    )
}

// MARK: - Header Validation

func validateHeader(_ headerData: Data) throws {
    guard let json = try? JSONSerialization.jsonObject(with: headerData) as? [String: Any] else {
        throw JWTError.malformedToken
    }
    guard let alg = json["alg"] as? String, alg == "HS256" else {
        throw JWTError.malformedToken
    }
    guard let typ = json["typ"] as? String, typ == "JWT" else {
        throw JWTError.malformedToken
    }
}

// MARK: - Full Token Validation Pipeline

func validateToken(_ token: String, config: JWTConfig = .default) throws -> JWTClaims {
    // Step 1: Split token into components
    let parts = token.split(separator: ".", omittingEmptySubsequences: false)
    guard parts.count == 3 else {
        throw JWTError.malformedToken
    }

    let headerB64 = String(parts[0])
    let payloadB64 = String(parts[1])
    let signatureB64 = String(parts[2])

    // Step 2: Verify HMAC signature FIRST (before any parsing)
    guard verifyHMACSignature(header: headerB64, payload: payloadB64, signature: signatureB64, secret: config.secret) else {
        throw JWTError.invalidSignature
    }

    // Step 3: Decode and validate header
    guard let headerData = base64URLDecode(headerB64) else {
        throw JWTError.invalidEncoding
    }
    try validateHeader(headerData)

    // Step 4: Decode and parse claims
    guard let payloadData = base64URLDecode(payloadB64) else {
        throw JWTError.invalidEncoding
    }
    let claims = try parseClaims(from: payloadData, config: config)

    // Step 5: Temporal validation
    let temporalResult = validateTokenTemporal(claims: claims, config: config)
    switch temporalResult {
    case .success:
        break
    case .failure(let error):
        throw error
    }

    return claims
}

// MARK: - Vapor Middleware

struct JWTAuthMiddleware: AsyncMiddleware {
    let config: JWTConfig

    init(config: JWTConfig = .default) {
        self.config = config
    }

    func respond(to request: Request, chainingTo next: AsyncResponder) async throws -> Response {
        guard let authHeader = request.headers[.authorization].first,
              authHeader.lowercased().hasPrefix("bearer ") else {
            throw Abort(.unauthorized, reason: "Missing authorization header")
        }

        let token = String(authHeader.dropFirst(7))

        do {
            let claims = try validateToken(token, config: config)
            // Store validated claims in request storage
            request.storage[JWTClaimsKey.self] = claims
        } catch let error as JWTError {
            switch error {
            case .invalidSignature:
                throw Abort(.unauthorized, reason: "Invalid token signature")
            case .tokenExpired:
                throw Abort(.unauthorized, reason: "Token has expired")
            case .tokenNotYetValid:
                throw Abort(.unauthorized, reason: "Token not yet valid")
            case .invalidIssuer:
                throw Abort(.unauthorized, reason: "Invalid token issuer")
            default:
                throw Abort(.unauthorized, reason: "Invalid token")
            }
        }

        return try await next.respond(to: request)
    }
}

struct JWTClaimsKey: StorageKey {
    typealias Value = JWTClaims
}

// MARK: - Protected Route Example

func configureRoutes(_ app: Application) {
    let protected = app.grouped(JWTAuthMiddleware())

    protected.get("admin", "users") { req -> Response in
        guard let claims = req.storage[JWTClaimsKey.self] else {
            throw Abort(.unauthorized)
        }
        guard claims.role == "admin" else {
            throw Abort(.forbidden, reason: "Admin access required")
        }
        // Return user list for admins
        return Response(status: .ok, body: .init(string: "{\"users\": []}"))
    }

    protected.get("profile") { req -> Response in
        guard let claims = req.storage[JWTClaimsKey.self] else {
            throw Abort(.unauthorized)
        }
        let profile = "{\"subject\": \"\(claims.subject)\", \"role\": \"\(claims.role)\"}"
        return Response(status: .ok, body: .init(string: profile))
    }
}
